// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.applock/** * NOUS — App lock state (Module 12, Pillar 5). * * Strategy §12.5 — observed by the UI as a [kotlinx.coroutines.flow.StateFlow] * from [AppLockManager]. The UI shows the lock screen when [LOCKED]. * *   - **UNLOCKED** — app is unlocked; sensitive features accessible. *   - **LOCKED** — app is locked; show lock screen. *   - **LOCKING** — in transition (e.g., user just pressed "lock now"; *     gives the UI a chance to fade out before showing the lock screen). * * State transitions: *   - UNLOCKED → LOCKING → LOCKED (on timeout or screen off). *   - LOCKED → UNLOCKED (on successful biometric/PIN auth). *   - LOCKING → UNLOCKED (user cancelled lock — not typical but possible). */sealed interface AppLockState {    /** App is unlocked; sensitive features accessible. */    data object Unlocked : AppLockState    /** App is locked; show lock screen. */    data object Locked : AppLockState    /** In transition — UI should fade content out before showing lock screen. */    data object Locking : AppLockState}/** * NOUS — Screen security level (Module 12, Pillar 5). * * Strategy §12.5 — controls per-screen [android.view.WindowManager.LayoutParams.FLAG_SECURE] * behavior: * *   - **NONE** — no FLAG_SECURE. Screenshots allowed. *   - **STANDARD** — FLAG_SECURE on sensitive screens only (settings, *     credential vault). Chat is NOT FLAG_SECURE (allows screen sharing). *   - **STRICT** — FLAG_SECURE on ALL screens. Disables screenshots entirely. * * Default is STANDARD. User can change in Settings → Privacy → Screen Security. */enum class ScreenSecurityLevel {    NONE,    STANDARD,    STRICT,}/** * NOUS — Screen type (Module 12, Pillar 5). * * Strategy §12.5 — each screen type has a different [ScreenSecurityLevel] * default (overridable by user preference). * *   - **CHAT** — main chat screen. FLAG_SECURE only if "hide preview in *     recents" is enabled (otherwise user can't share screenshots). *   - **SETTINGS** — settings screen showing API keys. Always FLAG_SECURE. *   - **CREDENTIAL_VAULT** — credential vault screen. Always FLAG_SECURE. *   - **MEMORY** — memory browser (episodic memories, semantic facts). *     FLAG_SECURE by default (user may have private content in memories). *   - **BACKUP** — backup/restore screen (may show file paths). FLAG_SECURE. */enum class ScreenType {    CHAT,    SETTINGS,    CREDENTIAL_VAULT,    MEMORY,    BACKUP,    ONBOARDING,    DEFAULT,}